#include <algorithm>
#include <cmath>
#include <cstdio>
#include <limits>
#include <initializer_list>
using namespace std;
using su2double=double;
using passivedouble=double;
#define FORCEINLINE inline
constexpr double PI_NUMBER=3.141592653589793;
template<class Type = su2double>
struct LimiterHelpers
{
  FORCEINLINE static Type epsilon() {return std::numeric_limits<passivedouble>::epsilon();}

  FORCEINLINE static Type umusclProjection(const Type& grad_proj, const Type& delta, const Type& kappa)
  {
    /*-------------------------------------------------------------------*/
    /*--- The MUSCL kappa-scheme reconstruction is typically written: ---*/
    /*---     V_L = V_i + 0.25 * dV_ij^kap, where                     ---*/
    /*---     dV_ij^kap = (1-kappa) dV_ij^upw + (1+kappa) dV_ij^cen,  ---*/
    /*---     dV_ij^cen = V_j - V_i,                                  ---*/
    /*---     dV_ij^upw = 2 grad(Vi) dot vector_ij - dV_ij^cen.       ---*/
    /*--- To maintain proper scaling for edge limiters, the result of ---*/
    /*--- this function is 0.5 * dV_ij^kap.                           ---*/
    /*-------------------------------------------------------------------*/
    const Type cent = 0.5 * delta;
    const Type upw = grad_proj - cent;
    return (1.0 - kappa) * upw + (1.0 + kappa) * cent;
  }

  FORCEINLINE static Type venkatFunction(const Type& proj, const Type& delta, const Type& eps2)
  {
    Type y = delta*(delta+proj) + eps2;
    return (y + delta*proj) / (y + 2*proj*proj);
  }

  FORCEINLINE static Type vanAlbadaFunction(const Type& proj, const Type& delta, const Type& eps)
  {
    return delta * (proj + delta) / (pow(proj, 2) + pow(delta, 2) + eps);
  }

  FORCEINLINE static Type raisedSine(const Type& dist)
  {
    Type factor = 0.5*(1.0+dist+sin(PI_NUMBER*dist)/PI_NUMBER);
    return max(0.0, min(factor, 1.0));
  }

  FORCEINLINE static Type r3Function(const Type& proj, const Type& delta, const Type& epsp)
  {
    Type Dp = fabs(delta);
    Type Dm = fabs(proj);
    if(Dp>(2.0*Dm)) return 1.0;
    Type y = pow(Dp, 3) + epsp;
    Type S3 = 4.0*Dm*Dm;
    return (y + Dp*S3) / (y + Dm*(delta*delta+S3));
  }

  FORCEINLINE static Type r4Function(const Type& proj, const Type& delta, const Type& epsp)
  {
    Type Dp = fabs(delta);
    Type Dm = fabs(proj);
    if(Dp>(2.0*Dm)) return 1.0;
    Type y = pow(Dp, 4) + epsp;
    Type S4 = 2.0*Dm*(Dp*Dp-2.0*Dm*(Dp-2.0*Dm));
    return (y + Dp*S4) / (y + Dm*(pow(delta,3)+S4));
  }

  FORCEINLINE static Type r5Function(const Type& proj, const Type& delta, const Type& epsp)
  {
    Type Dp = fabs(delta);
    Type Dm = fabs(proj);
    if(Dp>(2.0*Dm)) return 1.0;
    Type y = pow(Dp, 5) + epsp;
    Type S5 = 8.0*Dm*Dm*(Dp*Dp-2.0*Dm*(Dp-Dm));
    return (y + Dp*S5) / (y + Dm*(pow(delta,4)+S5));
  }
};
int main() {
  int fails=0,checks=0;
  for(double p : {0.1,0.5,1.0,2.0}) for(double d : {0.1,0.5,1.0,1.9}) {
    for(int order : {3,4,5}) {
      auto f = [order](double a,double b,double e) { if(order==3) return LimiterHelpers<>::r3Function(a,b,e); if(order==4) return LimiterHelpers<>::r4Function(a,b,e); return LimiterHelpers<>::r5Function(a,b,e); };
      ++checks; if(fabs(f(p,d,1e-3)-f(-p,-d,1e-3))>1e-10) ++fails;
    }
  }
  for(double sign : {1.0,-1.0}) { ++checks; if(fabs(LimiterHelpers<>::r4Function(sign,sign,0)-0.875)>1e-10) ++fails; }
  printf("checks=%d failures=%d R4_plus=%.15g R4_minus=%.15g\n",checks,fails,LimiterHelpers<>::r4Function(1,1,0),LimiterHelpers<>::r4Function(-1,-1,0));
}

